import{_ as t,o as s,c as r,a4 as i}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0035 — Plan de site, flux RSS et robots.txt : produits par l'API, relayés par le site public","description":"Extrait de docs/adr/0035-plan-de-site-flux-et-robots.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0035 — Plan de site, flux RSS et robots.txt : produits par l'API, relayés par le site public","description":"Extrait de docs/adr/0035-plan-de-site-flux-et-robots.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0035-plan-de-site-flux-et-robots.md","filePath":"developpeurs/adr/0035-plan-de-site-flux-et-robots.md"}`),o={name:"developpeurs/adr/0035-plan-de-site-flux-et-robots.md"};function n(a,e,l,u,d,c){return s(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0035--plan-de-site-flux-rss-et-robotstxt--produits-par-lapi-relayés-par-le-site-public" tabindex="-1">ADR-0035 — Plan de site, flux RSS et robots.txt : produits par l&#39;API, relayés par le site public <a class="header-anchor" href="#adr-0035--plan-de-site-flux-rss-et-robotstxt--produits-par-lapi-relayés-par-le-site-public" aria-label="Permalink to &quot;ADR-0035 — Plan de site, flux RSS et robots.txt : produits par l&#39;API, relayés par le site public {#adr-0035--plan-de-site-flux-rss-et-robotstxt--produits-par-lapi-relayés-par-le-site-public}&quot;">​</a></h1><p><strong>Date :</strong> 18 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit SEO du 18 septembre 2026 (constats « aucun sitemap XML », « flux RSS incomplet, lien de canal interne à l&#39;API », « aucun robots.txt ni X-Robots-Tag ») ; protocole sitemaps.org 0.9 ; RSS 2.0 ; RFC 9309 (Robots Exclusion Protocol) ; s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0034-adresses-publiques">ADR-0034</a><strong>Renvois ultérieurs :</strong> complétée par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0047-front-de-demarrage-optionnel">ADR-0047</a> (24 septembre 2026 : le front de démarrage relaie <code>robots.txt</code>, le plan de site et les flux).</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0034 a donné une adresse publique à chaque contenu et à chaque page, et une route qui dit ce qu&#39;une adresse désigne. Il manquait les trois fichiers qu&#39;un moteur de recherche lit en premier :</p><ul><li><strong>aucun plan de site</strong> : rien à déclarer dans les outils des moteurs, et le drapeau d&#39;exclusion <code>sitemap</code> du moteur de règles n&#39;avait aucun lecteur ;</li><li><strong>un flux RSS inutilisable</strong> : pas de lien par article, une langue toujours annoncée <code>fr</code>, un lien de canal qui pointait vers l&#39;adresse interne de l&#39;API ;</li><li><strong>aucun <code>robots.txt</code></strong>, ni pour le site public ni pour l&#39;API, dont le JSON et la documentation interactive pouvaient être indexés.</li></ul><p>Deux besoins propres aux collectivités s&#39;y ajoutent. Un site de <strong>recette</strong> ou en construction doit pouvoir rester hors des moteurs sans dépendre du serveur web. Et la question des <strong>robots d&#39;entraînement des IA</strong> se pose à chaque collectivité, qui doit pouvoir y répondre elle-même.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. L&#39;API produit les fichiers, et le site public les relaie.</strong> Le CMS reste « headless ». Une seule route, <code>GET /api/v1/public/files</code>, rend <code>robots.txt</code>, <code>sitemap.xml</code> (et ses parties <code>sitemap-2.xml</code>…) et les flux <code>/{préfixe}/rss.xml</code>, à partir du chemin demandé et de l&#39;hôte. La règle donnée au front tient en une ligne : <strong>un chemin en <code>.xml</code> ou <code>.txt</code> part vers cette route, tout autre chemin vers <code>/public/resolve</code>.</strong> Ces réponses sont mises en cache cinq minutes (<code>Cache-Control: public, max-age=300</code>).</p><p><strong>2. Le plan de site liste exactement ce que la résolution sert à un visiteur anonyme — ni plus, ni moins.</strong> Il contient :</p><ul><li>les pages visibles d&#39;un anonyme ;</li><li>les contenus publiés qu&#39;une vue liste publique servirait, en respectant l&#39;exclusion <code>sitemap</code>.</li></ul><p>Il ne contient pas les copies répliquées, dont l&#39;adresse de référence est sur leur site d&#39;origine (ADR-0034). Chaque contenu traduit porte ses <code>hreflang</code>. Un test résout chaque adresse du plan et exige qu&#39;elle désigne bien un contenu ou une page. Au-delà de 45 000 adresses, le plan devient un index de fichiers, sous la limite de 50 000 du protocole. Sans domaine, un site n&#39;a pas de plan : le protocole n&#39;admet que des adresses absolues.</p><p><strong>3. Chaque site peut être fermé aux moteurs.</strong> C&#39;est une case par site : le <code>robots.txt</code> interdit tout, le plan de site est vide, et chaque réponse de la résolution porte <code>noindex, nofollow</code>. <strong>Un site sans domaine est fermé par défaut, et un site créé par l&#39;usine à sites naît fermé même s&#39;il reçoit son domaine d&#39;emblée.</strong> Déclarer un domaine plus tard <strong>n&#39;ouvre pas</strong> le site : un domaine de recette ne doit pas exposer la recette par effet de bord. Seule exception : l&#39;installation, où l&#39;exploitant saisit le domaine de son site public en connaissance de cause.</p><p><strong>4. Le refus des robots d&#39;entraînement des IA est un réglage par site, désactivé par défaut.</strong> L&#39;information publique d&#39;une collectivité est faite pour circuler, et la décision lui revient, pas au CMS. La liste ne vise que les robots d&#39;<strong>entraînement</strong>, pas un assistant qui consulte une page à la demande d&#39;un usager. Elle est tenue dans une seule constante et <strong>vieillira</strong> : elle se révise comme un catalogue, pas comme une règle.</p><p><strong>5. Le flux RSS devient complet :</strong></p><ul><li>un lien et une description par article, cette description étant la même que celle de la résolution ;</li><li>la langue réellement servie ;</li><li>l&#39;adresse du site comme lien de canal ;</li><li><code>atom:link rel=&quot;self&quot;</code> vers l&#39;adresse publique du flux ;</li><li>une date de dernière construction.</li></ul><p>Un site fermé continue de servir ses flux, car un lecteur RSS n&#39;est pas un moteur de recherche.</p><p><strong>6. L&#39;API elle-même n&#39;est jamais indexée.</strong> Sa racine sert un <code>robots.txt</code> qui interdit tout, et chacune de ses réponses porte <code>X-Robots-Tag: noindex, nofollow</code>.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Laisser le front construire plan de site et flux</strong> à partir des listes</td><td>Chaque front réimplémenterait les exclusions (RGPD, copies répliquées, pages restreintes) : c&#39;est exactement la fuite que la clause de visibilité unique existe pour empêcher.</td></tr><tr><td><strong>Une route par fichier</strong></td><td>Trois règles de relais à écrire côté front au lieu d&#39;une, et une quatrième au premier fichier ajouté.</td></tr><tr><td><strong>Plan de site = tous les contenus publiés</strong></td><td>Il annoncerait des adresses qui répondent 404 (exclusion <code>listing</code>, copies répliquées) ou 401 (pages restreintes).</td></tr><tr><td><strong>Ouvrir le site dès qu&#39;un domaine est posé</strong></td><td>Un domaine de recette exposerait la recette.</td></tr><tr><td><strong>Robots d&#39;IA refusés par défaut</strong></td><td>Priverait par défaut les usagers d&#39;assistants qui citent l&#39;information publique ; le choix appartient à la collectivité.</td></tr><tr><td><strong>Fermer un site par le seul serveur web</strong></td><td>Hors de portée d&#39;un agent de collectivité, et invisible depuis le back-office.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Un site public se déclare aux moteurs en relayant deux chemins.</li><li>Le drapeau d&#39;exclusion <code>sitemap</code> du moteur de règles a enfin un effet.</li><li>Une recette ne peut plus être indexée par oubli.</li><li>Les flux s&#39;ouvrent dans un lecteur RSS, dans la bonne langue.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Le front doit relayer ces chemins.</strong> Un front qui ne le fait pas n&#39;a ni plan de site ni <code>robots.txt</code>, et la notice le dit.</li><li><strong>Tout site existant sans domaine devient fermé aux moteurs</strong> à la migration. Un site en production sans domaine déclaré était de toute façon incapable de produire une adresse absolue.</li><li>La liste des robots d&#39;IA devra être tenue à jour.</li><li>Le plan de site est calculé à chaque demande. Le cache de cinq minutes l&#39;absorbe pour une collectivité ; un très gros site demanderait un calcul en tâche de fond.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] En-têtes de cache et compression sur <code>/public/resolve</code> et les listes publiques — fait (audit du 26/09/2026, S14) : <code>app/core/public_cache.py</code> (liste blanche de chemins, <code>public, max-age</code> pour un visiteur, <code>private, no-store</code> avec <code>Authorization</code>, <code>no-store</code> sur erreur, GZip limité à ces réponses), réglage <code>PUBLIC_CACHE_MAX_AGE_SECONDS</code> ; tests <code>tests/test_cache_public.py</code>.</li><li>[ ] Redirection au changement de préfixe d&#39;un type ; contrôles réciproques au détachement d&#39;une page et au changement des langues d&#39;un site.</li><li>[x] Limitation de débit des routes publiques de résolution et de fichiers, qui sont appelées par le serveur du front plutôt que par les visiteurs. <strong>Close sans limite, sur décision du Product Owner (30/09/2026)</strong> : ces deux routes sont en lecture seule, n&#39;écrivent rien et ne déclenchent aucun envoi ; elles sont servies avec <code>public, max-age</code> (S14, <code>app/core/public_cache.py</code>), donc absorbées par tout cache placé devant l&#39;API. Une limite par adresse y compterait tout le trafic du serveur du front comme une seule adresse, et couperait le site public à la première affluence ; la corriger demanderait que le front relaie l&#39;adresse du visiteur et soit déclaré dans <code>FORWARDED_ALLOW_IPS</code>. Le déni de service volumétrique reste l&#39;affaire du proxy (Caddy, ADR-0045). À rouvrir si une mesure montre un abus.</li></ul>',26)])])}const g=t(o,[["render",n]]);export{m as __pageData,g as default};
